function denyAccess($url) {
    // Check if the URL is valid
    if (!preg_match('/^https?:\/\/[^\s]+$/i', $url)) {
        return "Invalid URL";
    }

    // Check if the URL is a website
    if (strpos($url, 'www.') !== false) {
        return "This is not a website";
    }

    // Check if the URL is a login page
    if (strpos($url, 'login') !== false || strpos($url, 'register') !== false) {
        return "This is a login page";
    }

    // Check if the URL is a script or executable file
    if (strpos($url, 'javascript:') !== false || strpos($url, 'exe') !== false) {
        return "This is a script or executable file";
    }

    // If none of the above conditions are met, deny access
    return "Access denied";
}

